package glitch

import data.glitch_lib

source_attributes := {"source", "source_url", "url", "from", "path"}
destination_attributes := {"destination", "dest", "to", "output"}
integrity_attributes := {"checksum", "hash", "md5", "sha256", "validation", "integrity", "verify"}
disabled_integrity_attributes := {"integrity", "enable_integrity_check", "versioning", "immutable", "lock"}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)

    # Check for data transmission attributes (source/destination)
    has_data_transmission := count({attr | attr := attrs[_]; source_attributes contains attr.name}) > 0
    has_data_transmission := count({attr | attr := attrs[_]; destination_attributes contains attr.name}) > 0

    # Check for missing or disabled integrity attributes
    has_integrity := count({attr | attr := attrs[_]; integrity_attributes contains attr.name}) > 0
    has_disabled_integrity := count({attr | attr := attrs[_]; disabled_integrity_attributes contains attr.name; 
                                        attr.value.ir_type == "Boolean"; attr.value.value == false}) > 0

    # If data transmission exists without proper integrity checks
    has_data_transmission
    not has_integrity
    not has_disabled_integrity

    result := {
        "type": "sec_no_int_check",
        "element": node,
        "path": parent.path,
        "description": "Missing integrity verification on data transmission - Data transmission without checksums, hash validation, or integrity checks (CWE-353)"
    }
}

