package glitch

import data.glitch_lib

source_patterns := {"source", "url", "source_url", "from"}
destination_patterns := {"destination", "dest", "target", "to"}
checksum_patterns := {"checksum", "hash", "md5", "sha256"}
integrity_patterns := {"integrity", "enable_integrity_check", "versioning", "immutable"}
signature_patterns := {"signature", "gpg", "pgp"}
verify_patterns := {"verify", "validation"}

matches_any(str, patterns) {
    pattern := patterns[_]
    glitch_lib.contains(str, pattern)
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]
    attrs := glitch_lib.all_attributes(node)

    has_source := count({attr | attr := attrs[_]; matches_any(attr.name, source_patterns)}) > 0
    has_destination := count({attr | attr := attrs[_]; matches_any(attr.name, destination_patterns)}) > 0

    has_checksum := count({attr | attr := attrs[_]; matches_any(attr.name, checksum_patterns)}) > 0
    has_integrity := count({attr | attr := attrs[_]; matches_any(attr.name, integrity_patterns)}) > 0
    has_signature := count({attr | attr := attrs[_]; matches_any(attr.name, signature_patterns)}) > 0
    has_verify := count({attr | attr := attrs[_]; matches_any(attr.name, verify_patterns)}) > 0

    (has_source or has_destination) and not has_checksum and not has_integrity and not has_signature and not has_verify

    result := {
        "type": "sec_no_int_check",
        "element": node,
        "path": parent.path,
        "description": "Missing integrity verification mechanisms in data transmission or storage (CWE-353)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
