    node := atomic_units[_]
    attrs := glitch_lib.all_attributes(node)

    script_patterns := {"script", "user_data", "inline_script"}
    has_script := count({attr | attr := attrs[_]; matches_any(attr.name, script_patterns)}) > 0
    has_verify := count({attr | attr := attrs[_]; matches_any(attr.name, verify_patterns)}) > 0

    has_script and not has_verify

    result := {
        "type": "sec_no_int_check",
        "element": node,
        "path": parent.path,
        "description": "Script execution without hash validation (CWE-353)"
    }
}

